import zlib
import struct

# Read all IDAT data together
idat_data = b''
with open('sunset.png', 'rb') as f:
    f.read(8)  # Skip signature

    while True:
        length_bytes = f.read(4)
        if not length_bytes:
            break
        length = struct.unpack('>I', length_bytes)[0]
        chunk_type = f.read(4)

        if chunk_type == b'IEND':
            f.read(4)
            break

        data = f.read(length)
        crc = f.read(4)  # Skip CRC for now
        if chunk_type == b'IDAT':
            idat_data += data

decompressed = zlib.decompress(idat_data)

# Try just extracting LSBs from R values that are in the "quiet" set
quiet_set = {0, 1, 255, 2, 254, 3, 253, 4, 252, 5, 251, 6, 250, 7, 249, 8, 248}

r_lsb = []
for i, byte in enumerate(decompressed):
    if i % 4 == 0:
        continue  # Filter byte
    if i % 4 == 1:
        if byte in quiet_set:
            r_lsb.append(str(byte & 1))

g_lsb = []
for i, byte in enumerate(decompressed):
    if i % 4 == 1:
        continue  # Skip R values
    if i % 4 == 2:
        if byte in quiet_set:
            g_lsb.append(str(byte & 1))

b_lsb = []
for i, byte in enumerate(decompressed):
    if i % 4 == 1:
        continue  # Skip R, G values
    if i % 4 == 3:
        if byte in quiet_set:
            b_lsb.append(str(byte & 1))

print(f'R LSB: {"".join(r_lsb)[:100]}')
print(f'G LSB: {"".join(g_lsb)[:100]}')
print(f'B LSB: {"".join(b_lsb)[:100]}')
EOF
